def factorialDigits(n):
    digs = [1]
    for m in range(2, n + 1):
        carry = 0
        for i in range(len(digs)):
            carry, digs[i] = divmod(digs[i] * m + carry, 10)
        while carry:
            carry, d = divmod(carry, 10)
            digs.append(d)
    digs.reverse()
    return digs
